LEFT JOIN catalog_public_endpoint_evidence p ON p.agentKey=d.agentKey AND p.endpointScope=d.endpointKey AND p.projectionVersion=1
WHERE d.declarationState='current' AND ((a.agentKey=OLD.agentKey AND d.endpointKey=OLD.endpointScope)) ON CONFLICT(agent_chainId,agent_agentKey,endpointKey) DO UPDATE SET agent_agentId=excluded.agent_agentId,agent_name=excluded.agent_name,agent_categoriesJson=excluded.agent_categoriesJson,agent_priority=excluded.agent_priority,agent_registeredAt=excluded.agent_registeredAt,agent_indexState=excluded.agent_indexState,cap_agentKey=excluded.cap_agentKey,cap_endpointKey=excluded.cap_endpointKey,cap_state=excluded.cap_state,cap_compatibilityState=excluded.cap_compatibilityState,cap_schemaHash=excluded.cap_schemaHash,cap_compatibilityCheckedAt=excluded.cap_compatibilityCheckedAt,cap_compatibilityExpiresAt=excluded.cap_compatibilityExpiresAt,cap_capabilityExpiresAt=excluded.cap_capabilityExpiresAt,cap_lastSuccessAt=excluded.cap_lastSuccessAt,cap_consecutiveFailures=excluded.cap_consecutiveFailures,cap_lastErrorCode=excluded.cap_lastErrorCode,cap_lastAttemptId=excluded.cap_lastAttemptId,evidence_latestPlatformOutcome=excluded.evidence_latestPlatformOutcome,evidence_latestPlatformObservedAt=excluded.evidence_latestPlatformObservedAt,evidence_latestPlatformExpiresAt=excluded.evidence_latestPlatformExpiresAt,evidence_latestPlatformProtocol=excluded.evidence_latestPlatformProtocol,evidence_latestPlatformSuccessId=excluded.evidence_latestPlatformSuccessId,evidence_hasBrowserProtocolSuccessEver=excluded.evidence_hasBrowserProtocolSuccessEver,evidence_latestQuoteOutcome=excluded.evidence_latestQuoteOutcome,evidence_latestQuoteIsBuyer=excluded.evidence_latestQuoteIsBuyer,evidence_latestQuoteExpiresAt=excluded.evidence_latestQuoteExpiresAt,evidence_hasBuyerVerifiedQuoteEver=excluded.evidence_hasBuyerVerifiedQuoteEver,declarationState=excluded.declarationState WHERE catalog_public_current_endpoints.agent_agentId IS NOT excluded.agent_agentId OR catalog_public_current_endpoints.agent_name IS NOT excluded.agent_name OR catalog_public_current_endpoints.agent_categoriesJson IS NOT excluded.agent_categoriesJson OR catalog_public_current_endpoints.agent_priority IS NOT excluded.agent_priority OR catalog_public_current_endpoints.agent_registeredAt IS NOT excluded.agent_registeredAt OR catalog_public_current_endpoints.agent_indexState IS NOT excluded.agent_indexState OR catalog_public_current_endpoints.cap_agentKey IS NOT excluded.cap_agentKey OR catalog_public_current_endpoints.cap_endpointKey IS NOT excluded.cap_endpointKey OR catalog_public_current_endpoints.cap_state IS NOT excluded.cap_state OR catalog_public_current_endpoints.cap_compatibilityState IS NOT excluded.cap_compatibilityState OR catalog_public_current_endpoints.cap_schemaHash IS NOT excluded.cap_schemaHash OR catalog_public_current_endpoints.cap_compatibilityCheckedAt IS NOT excluded.cap_compatibilityCheckedAt OR catalog_public_current_endpoints.cap_compatibilityExpiresAt IS NOT excluded.cap_compatibilityExpiresAt OR catalog_public_current_endpoints.cap_capabilityExpiresAt IS NOT excluded.cap_capabilityExpiresAt OR catalog_public_current_endpoints.cap_lastSuccessAt IS NOT excluded.cap_lastSuccessAt OR catalog_public_current_endpoints.cap_consecutiveFailures IS NOT excluded.cap_consecutiveFailures OR catalog_public_current_endpoints.cap_lastErrorCode IS NOT excluded.cap_lastErrorCode OR catalog_public_current_endpoints.cap_lastAttemptId IS NOT excluded.cap_lastAttemptId OR catalog_public_current_endpoints.evidence_latestPlatformOutcome IS NOT excluded.evidence_latestPlatformOutcome OR catalog_public_current_endpoints.evidence_latestPlatformObservedAt IS NOT excluded.evidence_latestPlatformObservedAt OR catalog_public_current_endpoints.evidence_latestPlatformExpiresAt IS NOT excluded.evidence_latestPlatformExpiresAt OR catalog_public_current_endpoints.evidence_latestPlatformProtocol IS NOT excluded.evidence_latestPlatformProtocol OR catalog_public_current_endpoints.evidence_latestPlatformSuccessId IS NOT excluded.evidence_latestPlatformSuccessId OR catalog_public_current_endpoints.evidence_hasBrowserProtocolSuccessEver IS NOT excluded.evidence_hasBrowserProtocolSuccessEver OR catalog_public_current_endpoints.evidence_latestQuoteOutcome IS NOT excluded.evidence_latestQuoteOutcome OR catalog_public_current_endpoints.evidence_latestQuoteIsBuyer IS NOT excluded.evidence_latestQuoteIsBuyer OR catalog_public_current_endpoints.evidence_latestQuoteExpiresAt IS NOT excluded.evidence_latestQuoteExpiresAt OR catalog_public_current_endpoints.evidence_hasBuyerVerifiedQuoteEver IS NOT excluded.evidence_hasBuyerVerifiedQuoteEver OR catalog_public_current_endpoints.declarationState IS NOT excluded.declarationState;
    END;
